/* Estantería: catálogo local-first. Los datos se guardan solo en el navegador. */
const KEY = 'estanteria-v1';
const uid = () => crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random());
const demo = {
  collections:[{id:'general',name:'Biblioteca general',description:'El fondo principal de la colección.',color:'#165a66'},{id:'club',name:'Club de lectura',description:'Lecturas que compartimos y comentamos.',color:'#ed8c52'},{id:'juvenil',name:'Juvenil',description:'Para lectores jóvenes y familias.',color:'#8772ae'}],
  books:[
    {id:'b1',title:'La sombra del viento',author:'Carlos Ruiz Zafón',isbn:'9788408172178',year:'2001',publisher:'Planeta',pages:'576',collection:'general',location:'Sala · Estante A · 3',tags:['misterio','Barcelona'],notes:'Ejemplar de consulta.',cover:'https://covers.openlibrary.org/b/isbn/9788408172178-M.jpg',copies:[{id:'c1',barcode:'EST-0001',status:'available',condition:'Bueno'}]},
    {id:'b2',title:'El olvido que seremos',author:'Héctor Abad Faciolince',isbn:'9788439736226',year:'2006',publisher:'Seix Barral',pages:'272',collection:'club',location:'Sala · Estante B · 1',tags:['memoria','biografía'],notes:'',cover:'https://covers.openlibrary.org/b/isbn/9788439736226-M.jpg',copies:[{id:'c2',barcode:'EST-0002',status:'loaned',condition:'Muy bueno'}]},
    {id:'b3',title:'Matilda',author:'Roald Dahl',isbn:'9788420464961',year:'1988',publisher:'Alfaguara',pages:'248',collection:'juvenil',location:'Infantil · Estante C · 2',tags:['infantil','clásico'],notes:'',cover:'https://covers.openlibrary.org/b/isbn/9788420464961-M.jpg',copies:[{id:'c3',barcode:'EST-0003',status:'available',condition:'Bueno'},{id:'c4',barcode:'EST-0004',status:'available',condition:'Aceptable'}]}
  ], loans:[{id:'l1',copyId:'c2',bookId:'b2',person:'María López',email:'',dateOut:'2026-08-16',dueDate:'2026-09-06',note:'Club de lectura',returned:false}], settings:{libraryName:'Papa Libro'}
};
let db = load(); let currentView='inicio'; let editingId=null; let stream=null;
function load(){try{const saved=JSON.parse(localStorage.getItem(KEY));return saved?.books ? saved : structuredClone(demo)}catch{return structuredClone(demo)}}
function save(){localStorage.setItem(KEY,JSON.stringify(db)); updateBadges()}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function getBook(id){return db.books.find(b=>b.id===id)} function getCollection(id){return db.collections.find(c=>c.id===id)}
function available(book){return book.copies.filter(c=>c.status==='available').length} function state(book){return !book.copies.length?'none':available(book)?'available':'out'}
function statusLabel(book){const n=available(book);return !book.copies.length?'Sin copias':n?`${n} disponible${n>1?'s':''}`:'Prestado'}
function cover(book, cls='cover'){return `<div class="${cls}">${book.cover?`<img src="${esc(book.cover)}" alt="Portada de ${esc(book.title)}" onerror="this.parentElement.innerHTML='${esc(book.title).slice(0,40)}'">`:esc(book.title)}</div>`}
function bookRow(book){return `<article class="book-row" data-book="${book.id}">${cover(book,'tiny-cover')}<div><strong>${esc(book.title)}</strong><small>${esc(book.author)} · ${esc(getCollection(book.collection)?.name||'Sin colección')}</small></div><span class="availability ${state(book)}">${statusLabel(book)}</span></article>`}
function empty(icon,text,button=''){return `<div class="empty"><span class="empty-icon">${icon}</span>${text}${button?`<br><button class="button small" data-action="${button}">Empezar</button>`:''}</div>`}
function updateBadges(){document.querySelector('#nav-count').textContent=db.books.length;document.querySelector('#loan-count').textContent=db.loans.filter(l=>!l.returned).length}
function render(){stopCamera();const c=document.querySelector('#content'); const view={inicio:home,catalogo:catalog,colecciones:collections,prestamos:loans,copias:inventory,ajustes:settings,ayuda:help}[currentView];c.innerHTML=view();document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===currentView));updateBadges();try{applyLocale()}catch{}}
function home(){const active=db.loans.filter(l=>!l.returned), recent=[...db.books].slice(-5).reverse();return `<section class="page"><div class="page-heading"><div><p class="eyebrow">${esc(db.settings.libraryName||'Tu biblioteca')}</p><h1>Todo tu fondo, a la vista</h1><p>Consulta, presta y encuentra tus libros sin depender del móvil.</p></div><button class="button" data-action="add-book">＋ Añadir libro</button></div><div class="dashboard-grid"><div><div class="stats"><div class="stat-card"><div class="num">${db.books.length}</div><p>Títulos catalogados</p></div><div class="stat-card"><div class="num">${db.books.reduce((n,b)=>n+b.copies.length,0)}</div><p>Copias físicas</p></div><div class="stat-card"><div class="num">${active.length}</div><p>Préstamos activos</p></div></div><div class="hero"><h2>¿Está ese libro en la biblioteca?</h2><p>Busca por título, autor o ISBN. Si tienes un lector USB, basta con escanear en el buscador.</p><button class="button" data-view="catalogo">Consultar catálogo</button></div><div class="panel"><div class="panel-title"><h2>Incorporaciones recientes</h2><button class="text-link" data-view="catalogo">Ver catálogo</button></div><div class="book-list">${recent.length?recent.map(bookRow).join(''):empty('📚','Aún no hay libros.')}</div></div></div><div><div class="panel"><div class="panel-title"><h2>Acciones rápidas</h2></div><div class="action-grid"><button class="action-card" data-action="scan"><i>▣</i><span><strong>Escanear ISBN</strong><small>Añade o encuentra un libro con la cámara</small></span></button><button class="action-card" data-action="add-book"><i>＋</i><span><strong>Alta manual</strong><small>Para libros sin código o ediciones antiguas</small></span></button><button class="action-card" data-view="prestamos"><i>↔</i><span><strong>Gestionar préstamos</strong><small>${active.length?`${active.length} libro${active.length>1?'s':''} fuera ahora`:'No hay préstamos activos'}</small></span></button></div></div><div class="panel" style="margin-top:22px"><div class="panel-title"><h2>Colecciones</h2><button class="text-link" data-view="colecciones">Gestionar</button></div><div class="collection-strip">${db.collections.map(x=>`<button class="collection-chip" data-collection="${x.id}"><b>${esc(x.name)}</b><small>${db.books.filter(b=>b.collection===x.id).length} títulos</small></button>`).join('')}</div></div></div></div></section>`}
function catalog(query=''){const books=db.books.filter(b=>[b.title,b.author,b.isbn,b.tags.join(' '),getCollection(b.collection)?.name].join(' ').toLowerCase().includes(query.toLowerCase()));return `<section class="page"><div class="page-heading"><div><p class="eyebrow">Catálogo</p><h1>Libros y ediciones</h1><p>${db.books.length} títulos · ${db.books.reduce((n,b)=>n+b.copies.length,0)} copias registradas</p></div><button class="button" data-action="add-book">＋ Añadir libro</button></div><div class="toolbar"><input class="search-input" id="catalog-search" type="search" placeholder="Filtrar el catálogo…" value="${esc(query)}"><select id="collection-filter"><option value="">Todas las colecciones</option>${db.collections.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><div class="view-toggle"><button title="Vista de portadas">▦</button><button title="Vista de lista" data-action="table-view">☷</button></div></div><div class="catalog-grid">${books.length?books.map(b=>`<article class="book-card" data-book="${b.id}">${cover(b)}<h3>${esc(b.title)}</h3><p>${esc(b.author)}</p><span class="availability ${state(b)}">${statusLabel(b)}</span></article>`).join(''):empty('⌕','No se han encontrado libros.', 'add-book')}</div></section>`}
function collections(){return `<section class="page"><div class="page-heading"><div><p class="eyebrow">Organización</p><h1>Colecciones</h1><p>Agrupa por sala, proyecto, público o temática.</p></div><button class="button" data-action="add-collection">＋ Nueva colección</button></div><div class="collection-grid">${db.collections.map(c=>`<article class="collection-card" data-collection="${c.id}" style="border-top-color:${esc(c.color||'#165a66')}"><h3>${esc(c.name)}</h3><p>${esc(c.description||'Sin descripción')}</p><footer>${db.books.filter(b=>b.collection===c.id).length} títulos · ${db.books.filter(b=>b.collection===c.id).reduce((n,b)=>n+b.copies.length,0)} copias</footer></article>`).join('')}</div></section>`}
function loans(){const active=db.loans.filter(l=>!l.returned), today=new Date().toISOString().slice(0,10);return `<section class="page"><div class="page-heading"><div><p class="eyebrow">Circulación</p><h1>Préstamos</h1><p>Un registro sencillo, claro y sin cuentas obligatorias.</p></div><button class="button" data-action="new-loan">＋ Registrar préstamo</button></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Libro</th><th>Persona</th><th>Salida</th><th>Devolución prevista</th><th>Estado</th><th></th></tr></thead><tbody>${active.length?active.map(l=>{const b=getBook(l.bookId), late=l.dueDate<today;return `<tr><td><div class="table-book">${cover(b,'tiny-cover')}<span><b>${esc(b.title)}</b><br><small class="muted">${esc(b.author)}</small></span></div></td><td>${esc(l.person)}<br><small class="muted">${esc(l.note||'')}</small></td><td>${l.dateOut}</td><td>${l.dueDate}</td><td><span class="availability ${late?'none':'out'}">${late?'Vencido':'En préstamo'}</span></td><td><button class="button small secondary" data-return="${l.id}">Devolver</button></td></tr>`}).join(''):`<tr><td colspan="6">${empty('↔','No hay ningún préstamo activo.')}</td></tr>`}</tbody></table></div></section>`}
function inventory(){const rows=db.books.flatMap(b=>b.copies.map(c=>({b,c})));return `<section class="page"><div class="page-heading"><div><p class="eyebrow">Control físico</p><h1>Inventario de copias</h1><p>Cada ejemplar tiene su propio código y estado.</p></div><button class="button" data-action="scan">▣ Buscar por código</button></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Libro</th><th>Ubicación</th><th>Estado</th><th>Conservación</th></tr></thead><tbody>${rows.length?rows.map(({b,c})=>`<tr><td><b>${esc(c.barcode||'—')}</b></td><td><a href="#" data-book="${b.id}">${esc(b.title)}</a></td><td>${esc(b.location||'Sin indicar')}</td><td><span class="availability ${c.status==='available'?'available':'out'}">${c.status==='available'?'Disponible':'Prestado'}</span></td><td>${esc(c.condition||'Sin valorar')}</td></tr>`).join(''):`<tr><td colspan="5">${empty('▦','Aún no hay copias registradas.')}</td></tr>`}</tbody></table></div></section>`}
function settings(){return `<section class="page"><div class="page-heading"><div><p class="eyebrow">Autonomía y respaldo</p><h1>Datos y ajustes</h1><p>Tu catálogo se guarda en este dispositivo. Exporta copias de seguridad con frecuencia.</p></div></div><div class="settings-grid"><article class="panel settings-card"><h2>Nombre de la biblioteca</h2><p>El nombre aparece en la pantalla de inicio.</p><input id="library-name" type="text" value="${esc(db.settings.libraryName||'')}" aria-label="Nombre de la biblioteca"><button class="button small" data-action="save-name">Guardar</button></article><article class="panel settings-card"><h2>Exportar catálogo</h2><p>Descarga todo: títulos, copias, colecciones y préstamos. Es tu copia de seguridad y puedes importarla después.</p><button class="button" data-action="export-json">Descargar respaldo JSON</button><button class="button secondary" data-action="export-csv">Exportar libros CSV</button></article><article class="panel settings-card"><h2>Importar datos</h2><p>Recupera una copia JSON de Estantería o incorpora una lista CSV con título, autor e ISBN.</p><button class="button" data-action="import">Elegir archivo</button></article><article class="panel settings-card"><h2>Empezar de nuevo</h2><p>Elimina todos los datos de este navegador. Primero descarga un respaldo: esta acción no se puede deshacer.</p><button class="button danger" data-action="clear-data">Borrar base de datos local</button></article></div></section>`}
function openBook(id){const b=getBook(id); editingId=id;document.querySelector('#book-dialog').innerHTML=`<div class="dialog-body"><div class="dialog-header"><div><p class="eyebrow">Ficha del libro</p></div><button class="close" data-close>×</button></div><div class="book-detail">${cover(b)}<div><h2>${esc(b.title)}</h2><p class="author">${esc(b.author)}</p><span class="availability ${state(b)}">${statusLabel(b)}</span><div class="meta"><div><small>ISBN</small><b>${esc(b.isbn||'—')}</b></div><div><small>Publicado</small><b>${esc(b.year||'—')}</b></div><div><small>Editorial</small><b>${esc(b.publisher||'—')}</b></div><div><small>Ubicación</small><b>${esc(b.location||'Sin indicar')}</b></div></div><div>${b.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="muted">${esc(b.notes||'')}</p><div class="dialog-actions"><button class="button secondary" data-action="edit-book">Editar ficha</button><button class="button" data-action="new-loan" ${available(b)?'':'disabled'}>Prestar una copia</button></div></div></div></div>`;document.querySelector('#book-dialog').showModal()}
function bookForm(book={copies:[{id:uid(),barcode:'',status:'available',condition:'Bueno'}],tags:[]}){editingId=book.id||null;document.querySelector('#book-dialog').innerHTML=`<form id="book-form" class="dialog-body"><div class="dialog-header"><div><p class="eyebrow">${book.id?'Editar':'Nueva ficha'}</p><h2>${book.id?'Actualizar libro':'Añadir un libro'}</h2></div><button type="button" class="close" data-close>×</button></div><div class="lookup-bar"><input id="isbn-lookup" inputmode="numeric" value="${esc(book.isbn||'')}" placeholder="ISBN (ej. 978...)" aria-label="ISBN"><button type="button" class="button secondary" data-action="lookup">Completar por ISBN</button><button type="button" class="button secondary" data-action="scan">▣ Cámara</button></div><div class="form-grid"><div class="field full"><label>Título *</label><input required name="title" value="${esc(book.title||'')}"></div><div class="field"><label>Autor o autora</label><input name="author" value="${esc(book.author||'')}"></div><div class="field"><label>Colección</label><select name="collection">${db.collections.map(c=>`<option value="${c.id}" ${book.collection===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Año</label><input name="year" inputmode="numeric" value="${esc(book.year||'')}"></div><div class="field"><label>Editorial</label><input name="publisher" value="${esc(book.publisher||'')}"></div><div class="field"><label>Ubicación</label><input name="location" placeholder="Sala · Estante · Balda" value="${esc(book.location||'')}"></div><div class="field"><label>Etiquetas</label><input name="tags" placeholder="separadas por comas" value="${esc((book.tags||[]).join(', '))}"></div><div class="field full"><label>Notas</label><textarea name="notes">${esc(book.notes||'')}</textarea></div><div class="field"><label>Cantidad de copias</label><input name="copyCount" type="number" min="0" value="${book.copies?.length||0}"></div><div class="field"><label>Estado de las copias</label><select name="condition"><option>Muy bueno</option><option selected>Bueno</option><option>Aceptable</option><option>Necesita reparación</option></select></div></div><div class="dialog-actions">${book.id?'<button type="button" class="button danger" data-action="delete-book">Eliminar</button>':''}<span style="flex:1"></span><button type="button" class="button secondary" data-close>Cancelar</button><button class="button">Guardar libro</button></div></form>`;document.querySelector('#book-dialog').showModal()}
function collectionForm(){document.querySelector('#simple-dialog').innerHTML=`<form id="collection-form" class="dialog-body"><div class="dialog-header"><h2>Nueva colección</h2><button type="button" class="close" data-close>×</button></div><div class="field"><label>Nombre *</label><input required name="name" autofocus placeholder="Ej. Historia local"></div><div class="field" style="margin-top:12px"><label>Descripción</label><textarea name="description" placeholder="¿Qué reúne esta colección?"></textarea></div><div class="dialog-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button">Crear colección</button></div></form>`;document.querySelector('#simple-dialog').showModal()}
function loanForm(bookId=''){const choices=db.books.filter(b=>available(b)>0);document.querySelector('#simple-dialog').innerHTML=`<form id="loan-form" class="dialog-body"><div class="dialog-header"><div><p class="eyebrow">Circulación</p><h2>Registrar préstamo</h2></div><button type="button" class="close" data-close>×</button></div><div class="form-grid"><div class="field full"><label>Libro y copia *</label><select name="bookCopy" required>${choices.map(b=>b.copies.filter(c=>c.status==='available').map(c=>`<option value="${b.id}|${c.id}" ${b.id===bookId?'selected':''}>${esc(b.title)} — ${esc(c.barcode||'Copia sin código')}</option>`).join('')).join('')}</select></div><div class="field"><label>Prestado a *</label><input name="person" required autofocus placeholder="Nombre de la persona"></div><div class="field"><label>Correo o teléfono</label><input name="email" placeholder="Opcional"></div><div class="field"><label>Fecha de salida</label><input type="date" name="dateOut" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Devolución prevista</label><input type="date" name="dueDate" value="${new Date(Date.now()+12096e5).toISOString().slice(0,10)}"></div><div class="field full"><label>Nota</label><input name="note" placeholder="Ej. préstamo para el club"></div></div><div class="dialog-actions"><button type="button" class="button secondary" data-close>Cancelar</button><button class="button">Confirmar préstamo</button></div></form>`;document.querySelector('#simple-dialog').showModal()}
async function lookup(){const isbn=document.querySelector('#isbn-lookup').value.replace(/[^0-9Xx]/g,'');if(!isbn)return toast('Escribe o escanea un ISBN primero.');toast('Buscando ficha…');try{const r=await fetch(`https://openlibrary.org/api/books?bibkeys=ISBN:${isbn}&format=json&jscmd=data`);const data=(await r.json())[`ISBN:${isbn}`];if(!data)throw Error();const form=document.querySelector('#book-form').elements;form.title.value=data.title||'';form.author.value=(data.authors||[]).map(x=>x.name).join(', ');form.year.value=data.publish_date?.match(/\d{4}/)?.[0]||'';form.publisher.value=(data.publishers||[]).map(x=>x.name).join(', ');document.querySelector('#isbn-lookup').value=isbn;toast('Ficha completada. Revisa los datos antes de guardar.')}catch{toast('No se encontró una ficha. Puedes completarla manualmente.')}}
async function scan(){const d=document.querySelector('#simple-dialog');d.innerHTML=`<div class="dialog-body"><div class="dialog-header"><div><p class="eyebrow">Lector de códigos</p><h2>Escanear ISBN</h2></div><button class="close" data-close>×</button></div><div class="camera-box" id="camera-box"><p>Preparando la cámara…</p></div><p class="muted" style="font-size:.8rem">Si no se abre la cámara, escribe el ISBN en el formulario. También puedes usar un lector USB: actúa como un teclado.</p></div>`;d.showModal();if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){document.querySelector('#camera-box').innerHTML='<p>Este navegador no ofrece lectura por cámara.<br>Usa el campo ISBN o un lector USB.</p>';return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const v=document.createElement('video');v.autoplay=true;v.playsInline=true;document.querySelector('#camera-box').replaceChildren(v);v.srcObject=stream;const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128']});const tick=async()=>{if(!stream)return;try{const codes=await detector.detect(v);if(codes[0]?.rawValue){const code=codes[0].rawValue;stopCamera();d.close();const field=document.querySelector('#isbn-lookup');if(field){field.value=code;lookup()}else{const b=db.books.find(x=>x.isbn.replace(/[^0-9X]/gi,'')===code||x.copies.some(c=>c.barcode===code));b?openBook(b.id):bookForm({isbn:code,copies:[{id:uid(),barcode:'',status:'available',condition:'Bueno'}],tags:[]})}return}}catch{}requestAnimationFrame(tick)};tick()}catch{document.querySelector('#camera-box').innerHTML='<p>No se pudo acceder a la cámara.<br>Comprueba el permiso del navegador.</p>'}}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2900)}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function exportCSV(){const rows=[['title','author','isbn','year','publisher','collection','location','tags','copies','available']];db.books.forEach(b=>rows.push([b.title,b.author,b.isbn,b.year,b.publisher,getCollection(b.collection)?.name||'',b.location,b.tags.join(';'),b.copies.length,available(b)]));download('estanteria-libros.csv',rows.map(r=>r.map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv;charset=utf-8')}
function importData(file){const reader=new FileReader();reader.onload=()=>{try{if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(reader.result);if(!Array.isArray(data.books))throw Error();db={collections:data.collections||[],books:data.books,loans:data.loans||[],settings:data.settings||{}}}else{const lines=reader.result.trim().split(/\r?\n/);const headers=lines.shift().split(',').map(x=>x.replaceAll('"','').trim().toLowerCase());lines.forEach(line=>{const vals=line.match(/("(?:[^"]|"")*"|[^,]*)(?:,|$)/g).map(v=>v.replace(/^"|",?$/g,'').replaceAll('""','"'));const o=Object.fromEntries(headers.map((h,i)=>[h,vals[i]||'']));const cid=db.collections[0]?.id||'general';db.books.push({id:uid(),title:o.title||'Sin título',author:o.author||'',isbn:o.isbn||'',year:o.year||'',publisher:o.publisher||'',collection:cid,location:o.location||'',tags:(o.tags||'').split(/[;,]/).filter(Boolean),notes:'',cover:o.isbn?`https://covers.openlibrary.org/b/isbn/${o.isbn}-M.jpg`:'',copies:Array.from({length:Math.max(1,+o.copies||1)},(_,i)=>({id:uid(),barcode:`IMP-${Date.now().toString().slice(-5)}${i}`,status:'available',condition:'Bueno'}))})})}save();render();toast('Datos importados correctamente.')}catch{toast('No se pudo leer ese archivo.')} };reader.readAsText(file)}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action],[data-view],[data-book],[data-collection],[data-return],[data-close]');if(!btn)return;if('close' in btn.dataset){stopCamera();btn.closest('dialog').close();return}if(btn.dataset.book){e.preventDefault();openBook(btn.dataset.book);return}if(btn.dataset.collection){currentView='catalogo';render();setTimeout(()=>{document.querySelector('#collection-filter').value=btn.dataset.collection;filterCatalog()},0);return}if(btn.dataset.view){currentView=btn.dataset.view;render();return}if(btn.dataset.return){const l=db.loans.find(x=>x.id===btn.dataset.return);l.returned=true;const b=getBook(l.bookId);b.copies.find(c=>c.id===l.copyId).status='available';save();render();toast('Libro devuelto y disponible.');return}switch(btn.dataset.action){case'add-book':bookForm();break;case'edit-book':bookForm(getBook(editingId));break;case'delete-book':if(confirm('¿Eliminar esta ficha y todas sus copias?')){db.books=db.books.filter(b=>b.id!==editingId);db.loans=db.loans.filter(l=>l.bookId!==editingId);save();document.querySelector('#book-dialog').close();render();toast('Libro eliminado.')}break;case'add-collection':collectionForm();break;case'new-loan':loanForm(editingId);break;case'lookup':lookup();break;case'scan':scan();break;case'export-json':download('estanteria-respaldo.json',JSON.stringify(db,null,2),'application/json');toast('Respaldo descargado.');break;case'export-csv':exportCSV();toast('CSV descargado.');break;case'import':document.querySelector('#import-file').click();break;case'clear-data':if(confirm('Esto eliminará el catálogo local. ¿Seguro?')){localStorage.removeItem(KEY);db={collections:[],books:[],loans:[],settings:{libraryName:'Papa Libro'}};save();render();toast('Base de datos local eliminada.')}break;case'save-name':db.settings.libraryName=document.querySelector('#library-name').value.trim()||'Mi Estantería';save();toast('Nombre guardado.');break;case'table-view':toast('La vista de lista está disponible en Inventario.');break}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target, fd=new FormData(f);if(f.id==='book-form'){const old=editingId?getBook(editingId):null;const count=Math.max(0,+fd.get('copyCount')||0);const copies=(old?.copies||[]).slice(0,count);while(copies.length<count)copies.push({id:uid(),barcode:`EST-${String(Date.now()).slice(-5)}${copies.length+1}`,status:'available',condition:fd.get('condition')});const isbn=document.querySelector('#isbn-lookup').value.trim();const b={id:old?.id||uid(),title:fd.get('title').trim(),author:fd.get('author').trim(),isbn,year:fd.get('year').trim(),publisher:fd.get('publisher').trim(),collection:fd.get('collection'),location:fd.get('location').trim(),tags:fd.get('tags').split(',').map(x=>x.trim()).filter(Boolean),notes:fd.get('notes').trim(),cover:isbn?`https://covers.openlibrary.org/b/isbn/${isbn.replace(/[^0-9X]/gi,'')}-M.jpg`:old?.cover||'',copies};if(old)Object.assign(old,b);else db.books.push(b);save();document.querySelector('#book-dialog').close();render();toast(old?'Ficha actualizada.':'Libro añadido al catálogo.')}if(f.id==='collection-form'){db.collections.push({id:uid(),name:fd.get('name').trim(),description:fd.get('description').trim(),color:'#165a66'});save();document.querySelector('#simple-dialog').close();render();toast('Colección creada.')}if(f.id==='loan-form'){const [bookId,copyId]=fd.get('bookCopy').split('|'), b=getBook(bookId);b.copies.find(c=>c.id===copyId).status='loaned';db.loans.push({id:uid(),bookId,copyId,person:fd.get('person').trim(),email:fd.get('email').trim(),dateOut:fd.get('dateOut'),dueDate:fd.get('dueDate'),note:fd.get('note').trim(),returned:false});save();document.querySelector('#simple-dialog').close();document.querySelector('#book-dialog').close();currentView='prestamos';render();toast('Préstamo registrado.')}});
function filterCatalog(){const q=document.querySelector('#catalog-search').value, c=document.querySelector('#collection-filter').value;document.querySelector('.catalog-grid').innerHTML=db.books.filter(b=>(!c||b.collection===c)&&[b.title,b.author,b.isbn,b.tags.join(' ')].join(' ').toLowerCase().includes(q.toLowerCase())).map(b=>`<article class="book-card" data-book="${b.id}">${cover(b)}<h3>${esc(b.title)}</h3><p>${esc(b.author)}</p><span class="availability ${state(b)}">${statusLabel(b)}</span></article>`).join('')||empty('⌕','No se han encontrado libros.','add-book')}
document.addEventListener('input',e=>{if(e.target.id==='catalog-search')filterCatalog()});document.addEventListener('change',e=>{if(e.target.id==='collection-filter')filterCatalog();if(e.target.id==='import-file')importData(e.target.files[0])});document.querySelector('#global-search').addEventListener('input',e=>{const q=e.target.value;if(q.length>1){currentView='catalogo';render();document.querySelector('#catalog-search').value=q;filterCatalog()}});document.querySelector('#quick-add').onclick=()=>bookForm();document.querySelector('.menu-button').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#global-search').focus()}});render();
function help(){const guideStem={es:'GUIA_FACIL_PAPA_LIBRO',en:'PAPA_LIBRO_EASY_GUIDE',fr:'GUIDE_SIMPLE_PAPA_LIBRO',pt:'GUIA_FACIL_PAPA_LIVRO'}[locale]||'GUIA_FACIL_PAPA_LIBRO';return `<section class="page help-layout"><div class="page-heading"><div><p class="eyebrow">Guía de uso</p><h1>¿Necesitas ayuda?</h1><p>Todo lo importante, explicado paso a paso y sin palabras complicadas.</p></div></div><div class="help-intro"><h2>Lo esencial</h2><p>Estantería sirve para saber si tenemos un libro, dónde está y a quién se lo hemos prestado. Para empezar basta con añadir el título, la ubicación y el número de copias.</p></div><div class="help-grid"><article class="panel help-card"><h2>Buscar un libro</h2><ol><li>Usa la caja de búsqueda de arriba.</li><li>Escribe el título o el apellido del autor.</li><li><b>Disponible</b> significa que está en la biblioteca; <b>Prestado</b>, que está fuera.</li></ol><button class="button secondary small" data-view="catalogo">Ir al catálogo</button></article><article class="panel help-card"><h2>Añadir con código de barras</h2><ol><li>Pulsa <b>Añadir libro</b>.</li><li>Escribe los números que hay debajo del código.</li><li>Pulsa <b>Completar por ISBN</b>.</li></ol><p>También puedes usar el botón Cámara. Si no funciona, escribe los números a mano.</p><button class="button secondary small" data-action="add-book">Añadir libro</button></article><article class="panel help-card"><h2>Prestar y devolver</h2><ol><li>Abre un libro disponible y pulsa <b>Prestar una copia</b>.</li><li>Escribe el nombre de la persona.</li><li>Para devolverlo, abre <b>Préstamos</b> y pulsa <b>Devolver</b>.</li></ol><button class="button secondary small" data-view="prestamos">Ver préstamos</button></article><article class="panel help-card"><h2>Guardar una copia</h2><ol><li>Abre <b>Datos y ajustes</b>.</li><li>Pulsa <b>Descargar respaldo JSON</b>.</li><li>Guarda el archivo en una carpeta fácil de encontrar.</li></ol><div class="help-warning"><b>Importante:</b> haz una copia antes de borrar datos o cambiar de ordenador.</div><button class="button secondary small" data-view="ajustes">Ir a datos y ajustes</button></article></div><div class="panel help-card" style="margin-top:17px"><h2>Guías para leer o imprimir</h2><p>También tienes la guía completa en formatos habituales:</p><p><a href="docs/${guideStem}.pdf" target="_blank">Abrir la guía en PDF</a> · <a href="docs/${guideStem}.html" target="_blank">Abrir la guía como página</a> · <a href="docs/${guideStem}.docx">Descargar la guía para Word</a></p></div></section>`}
