const LOCALES=['es','en','fr','pt'];
let locale=localStorage.getItem('papalibro-language')||'es';
if(!LOCALES.includes(locale))locale='es';
const translatedNodes=new WeakMap(),translatedAttributes=new WeakMap();
function translateText(value){if(locale==='es')return value;const labels=I18N[locale]||{};let out=labels[value]||value;return out.replace(/^(\d+) disponible(s)?$/,(_,n)=>locale==='fr'?`${n} disponible${n>1?'s':''}`:locale==='pt'?`${n} disponível${n>1?'is':''}`:`${n} available`).replace(/^(\d+) títulos$/,(_,n)=>locale==='fr'?`${n} titres`:locale==='pt'?`${n} títulos`:`${n} titles`).replace(/^(\d+) copias$/,(_,n)=>locale==='fr'?`${n} exemplaires`:locale==='pt'?`${n} exemplares`:`${n} copies`)}
function applyLocale(){document.documentElement.lang=locale;document.title=locale==='es'?'Papa Libro — catálogo de libros':locale==='en'?'Papa Libro — book catalogue':locale==='fr'?'Papa Libro — catalogue de livres':'Papa Livro — catálogo de livros';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),nodes=[];let node;while(node=walker.nextNode())nodes.push(node);nodes.forEach(n=>{if(n.parentElement?.closest('script,style'))return;const original=translatedNodes.get(n)||n.nodeValue;translatedNodes.set(n,original);const match=original.match(/^(\s*)([\s\S]*?)(\s*)$/);n.nodeValue=match[1]+translateText(match[2])+match[3]});document.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>{let originals=translatedAttributes.get(el);if(!originals){originals=new Map();translatedAttributes.set(el,originals)};['placeholder','title','aria-label'].forEach(attr=>{if(!el.hasAttribute(attr))return;const original=originals.get(attr)||el.getAttribute(attr);originals.set(attr,original);el.setAttribute(attr,translateText(original))})});const picker=document.querySelector('#language-select');if(picker)picker.value=locale}
function setLocale(next){locale=LOCALES.includes(next)?next:'es';localStorage.setItem('papalibro-language',locale);render();applyLocale()}
setTimeout(()=>{document.querySelector('#language-select')?.addEventListener('change',e=>setLocale(e.target.value));new MutationObserver(()=>applyLocale()).observe(document.body,{childList:true,subtree:true});applyLocale()},0);
